extension Ws.Mirror.Relink {
    /// Approves the outcome a linked server proposed for its relink of the vault: which server becomes the core, the
    /// mode, and what this vault gains and loses (entries replaced or removed here, kept as held changes or conflict
    /// copies). The other server then carries it out; this server prepares only that plan (the same hash and counts,
    /// its tree unchanged): a changed plan or tree voids the approval. `confirm` is the vault's name, typed. Super
    /// admins, people only; the keys step-up in the console; audited on both servers.
    public enum Approve: WsRequest {
        public static let command = WsCommand.mirrorRelinkApprove

        public struct Payload: Codable, Hashable, Sendable {
            /// Vault id. Minimum 0.
            public var vaultID: Int64
            /// The vault's name, typed exactly.
            public var confirm: String

            public init(vaultID: Int64, confirm: String) {
                self.vaultID = vaultID
                self.confirm = confirm
            }

            enum CodingKeys: String, CodingKey {
                case vaultID = "vault_id"
                case confirm
            }
        }

        public struct Response: Codable, Hashable, Sendable {
            /// Minimum 0.
            public var vaultID: Int64
            public var vaultName: String
            public var relinkUid: String
            /// One of the known values in `Phase`; a newer daemon may send others.
            public var phase: String
            /// The linked server asking.
            public var peer: Peer
            /// Who asked, on that server.
            public var askedBy: String
            /// What this server holds of the vault.
            public var status: String
            public var createdAt: Int64
            /// Both servers agree, each by a super admin: to compare (the responder accepts the request), then to the
            /// outcome (it approves it).
            public var handshake: Handshake?

