extension Ws.Mirror.Relink {
    /// The relinks linked servers ask of this server's vaults that wait for an answer here (requested: accept or
    /// decline; proposed: approve or decline the outcome), and those accepted or approved and not carried out yet: who
    /// asks, which vault, what accepting lets them see, the outcome in plain words. Super admins.
    public enum Pending: WsRequest {
        public static let command = WsCommand.mirrorRelinkPending
        public typealias Payload = WsEmpty

        public struct Response: Codable, Hashable, Sendable {
