                /// The linked server asking.
                public var peer: Peer
                /// Who asked, on that server.
                public var askedBy: String
                /// What this server holds of the vault.
                public var status: String
                public var createdAt: Int64
                /// Both servers agree, each by a super admin: to compare (the responder accepts the request), then to
                /// the outcome (it approves it).
                public var handshake: Handshake?

                public init(vaultID: Int64, vaultName: String, relinkUid: String, phase: String, peer: Peer,
                            askedBy: String, status: String, createdAt: Int64, handshake: Handshake? = nil) {
                    self.vaultID = vaultID
                    self.vaultName = vaultName
                    self.relinkUid = relinkUid
                    self.phase = phase
                    self.peer = peer
                    self.askedBy = askedBy
                    self.status = status
